Section SO.
  Variables (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (x1 x9 x10 x11 x16 x19 x22 x23 x24 x25 x26 x27 x30 x31 : word).
  Variables (m : fmem) (WK tl nbS : Z) (ws : list Z) (js : list byte).
  Variable POST : machine_state -> Prop.
  Notation RS := (WK + 52).
  Notation SY := (WK + 980).
  Notation HW := (WK + 1236).
  Hypothesis HTL : 1 <= tl <= 12.
  Hypothesis HNS : 0 <= nbS <= 256.
  Hypothesis LWS : zlen ws = nbS.
  Hypothesis WSR : Forall (fun w => 0 <= w <= tl) ws.
  Hypothesis HJS : length js = 256%nat.
  Hypothesis HWK : 0 < WK /\ WK + 1492 <= 2^47.

  Definition so_inv (m1 : fmem) (rs : list Z) (syms : list (option Z)) (rsw : list word) : Prop :=
    u32arr psegs m1 RS rsw /\ length rsw = 13%nat /\ agree tl rs rsw /\ zlen rs = 13
    /\ u8arr psegs m1 SY (omerge js syms) /\ length syms = 256%nat
    /\ bytes_at psegs m1 HW (map (Z_to_bv 8) ws)
    /\ munch [(RS, RS + 52); (SY, SY + 256)] m m1 /\ wmono psegs m m1 /\ mem_inv psegs m1.

  Notation ST1 pc mm n x5 x6 x7 x13 x17 x28 x29 :=
    (MS (mkR x1 sp gp tp x5 x6 x7 (Z_to_bv 64 WK) x9 x10 x11 (Z_to_bv 64 SY) x13 (Z_to_bv 64 RS) (Z_to_bv 64 n) x16 x17
             (Z_to_bv 64 HW) x19 (Z_to_bv 64 nbS) (Z_to_bv 64 nbS) x22 x23 x24 x25 x26 x27 x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

