             x28 x29 x30 x31)
        F (Z_to_bv 64 pc) fc None mm (seg_rom psegs)).

  (* [comment removed for export] *)
  Lemma so4 : forall f n rs syms rsw m1 r (x5 x6 x7 x28 x29 : word),
    sort_loop f n ws rs syms = Ok r -> Z.of_nat f = nbS - n -> 0 <= n -> n + 4 <= nbS -> so_inv m1 rs syms rsw ->
    (forall m2 rs' syms' rsw' (y5 y6 y7 y13 y17 y28 y29 : word), r = (rs', syms') -> so_inv m2 rs' syms' rsw' ->
       evt psegs POST (ST1 0x13680 m2 nbS y5 y6 y7 y13 y17 y28 y29)) ->
    evt psegs POST (ST4 0x135b4 m1 n x5 x6 x7 x28 x29).
